<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Bars\{BarsOfficialAdapter,BarsSections,BarsStatistics,ProviderFactory,ProviderResult};use StudPulse\Database\DB;use StudPulse\Domain\{Access,Input,LessonLibrary,UserAvatar};use StudPulse\Security\{Auth,RateLimit};use StudPulse\Integrations\{Calendar,MpeiSchedule,ScheduleSubgroups};final class StudyController{public function campus(Auth$a):array{return['items'=>require ROOT.'/config/campus.php','source'=>'План кампуса НИУ МЭИ и OpenStreetMap','verifiedAt'=>'2026-11-14','mapProvider'=>'openfreemap',];}public static function range():array{$tz=new \DateTimeZone('Europe/Moscow');$today=(new \DateTimeImmutable('now',$tz))->format('Y-m-d');$from=$_GET['from']??$today;$to=$_GET['to']??$from;foreach([$from,$to]as$s){if(!is_string($s)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$s)||!($d=\DateTimeImmutable::createFromFormat('!Y-m-d',$s,$tz))||$d->format('Y-m-d')!==$s){throw new ApiError(422,'INVALID_RANGE','Некорректный диапазон дат');}}$start=new \DateTimeImmutable($from,$tz);$end=(new \DateTimeImmutable($to,$tz))->modify('+1 day');if($end<=$start||$end->getTimestamp()-$start->getTimestamp()>93*86400){throw new ApiError(422,'INVALID_RANGE','Диапазон не более 92 дней');}return[$start->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s'),$end->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s')];}public function schedule(Auth$a):mixed{[$from,$to]=self::range();$provider=ProviderFactory::make($a);if(($_GET['journal']??'')==='1'){$a->require('headman:write');$group=$a->journal();if($provider instanceof BarsOfficialAdapter){return ScheduleSubgroups::combineParallel(MpeiSchedule::forGroup($group['canonical_code'],$from,$to));}}if($provider instanceof BarsOfficialAdapter){$schedule=LessonLibrary::mark($a,$provider->getMySchedule($from,$to,true));return self::offlineSchedule($a,ScheduleSubgroups::combineParallel(ScheduleSubgroups::forUser($schedule,$a->user['id']),preserveMaterials:true));}return self::offlineSchedule($a,$provider->getMySchedule($from,$to));}private static function offlineSchedule(Auth$a,ProviderResult$schedule):ProviderResult{return new ProviderResult($schedule->items,$schedule->source,$schedule->observedAt,$schedule->fixture,[...$schedule->details,'offlineContext'=>$a->offlineContext()]);}public function subgroups(Auth$a):array{$provider=ProviderFactory::make($a);if(!$provider instanceof BarsOfficialAdapter){return['items'=>[]];}$start=new \DateTimeImmutable('monday this week',new \DateTimeZone('Europe/Moscow'));$utc=new \DateTimeZone('UTC');$from=$start->modify('-14 days')->setTimezone($utc)->format('Y-m-d H:i:s');$to=$start->modify('+28 days')->setTimezone($utc)->format('Y-m-d H:i:s');return ScheduleSubgroups::options($provider->getMySchedule($from,$to,true));}public function ruzTeacher(Auth$a):ProviderResult{[$from,$to]=self::range();if(strtotime($to)-strtotime($from)>7*86400){throw new ApiError(422,'INVALID_RANGE','Выберите одну учебную неделю.');}RateLimit::check('ruz-teacher:'.$a->user['id'],20,300);return MpeiSchedule::forTeacher(Input::text($_GET,'name',120),$from,$to);}public function subjects(Auth$a):array{$m=$a->membership;if($m===null){return['items'=>[]];}return['items'=>DB::all('SELECT s.*,f.user_id IS NOT NULL AS favorite FROM subjects s LEFT JOIN favorite_subjects f ON f.subject_id=s.id AND f.user_id=? WHERE s.group_id=? AND s.term_id=? AND s.archived_at IS NULL ORDER BY s.title',[$a->user['id'],$m['group_id'],$m['term_id']])];}public function subject(Auth$a,string$id):array{$s=Access::subject($a,$id);$s['topics']=json_decode($s['topics']??'[]',true);$s['assessments']=DB::all('SELECT * FROM assessments WHERE subject_id=?',[$id]);return$s;}public function grades(Auth$a):mixed{return ProviderFactory::make($a)->getGradesAndAssessments($a->membership['term_id']??'');}public function rating(Auth$a):ProviderResult{$provider=ProviderFactory::make($a);$term=$a->membership['term_id']??'';$result=$provider instanceof BarsOfficialAdapter?$provider->getRating($term,$this->fresh($a,'rating')):$provider->getRating($term);if($result->fixture){return$result;}$rating=BarsStatistics::rating($result);$userId=$a->user['id'];$semester=$rating['semester'];if($rating['metrics']&&$result->observedAt&&empty($result->details['stale'])){$observed=new \DateTimeImmutable($result->observedAt);$date=$observed->setTimezone(new \DateTimeZone('Europe/Moscow'))->format('Y-m-d');$at=$observed->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s');foreach($rating['metrics']as$metric){DB::run('INSERT INTO bars_rating_points(user_id,semester,metric,observed_date,value,observed_at) VALUES(?,?,?,?,?,?) AS incoming ON DUPLICATE KEY UPDATE value=IF(incoming.observed_at>=bars_rating_points.observed_at,incoming.value,bars_rating_points.value),observed_at=GREATEST(bars_rating_points.observed_at,incoming.observed_at)',[$userId,$semester,$metric['id'],$date,$metric['value'],$at]);}}$history=DB::all('SELECT metric,observed_date AS date,value FROM bars_rating_points WHERE user_id=? AND semester=? AND observed_date>=DATE_SUB(UTC_DATE(),INTERVAL 120 DAY) ORDER BY observed_date',[$userId,$semester]);return new ProviderResult($result->items,$result->source,$result->observedAt,false,[...$result->details,...$rating,'history'=>$history]);}public function attendance(Auth$a):ProviderResult{$provider=ProviderFactory::make($a);$term=$a->membership['term_id']??'';$result=$provider instanceof BarsOfficialAdapter?$provider->getAttendance($term,$this->fresh($a,'attendance')):$provider->getAttendance($term);if($result->fixture||isset($result->details['attendance'])){return$result;}$details=$result->details;$details['attendance']=BarsStatistics::attendance($details['blocks']??[]);return new ProviderResult($result->items,$result->source,$result->observedAt,false,$details);}public function attendanceQr(Auth$a,#[\SensitiveParameter]Request$r):array{$a->browserOnly();$raw=$r->body['raw']??null;if(!is_string($raw))throw new ApiError(422,'BARS_QR_INVALID','Отсканируйте QR-код БАРС МЭИ.');RateLimit::check('bars-qr:'.$a->user['id'],8);$result=$this->bars($a)->verifyAttendanceQr($raw);return['confirmed'=>($result->details['confirmed']??false)===true];}private function fresh(Auth$a,string$resource):bool{if(($_GET['fresh']??'')!=='1'){return false;}RateLimit::check('refresh:'.$resource.':'.$a->user['id'],1,30);return true;}public function barsSections(Auth$a):ProviderResult{return$this->bars($a)->sections();}public function barsSection(Auth$a):ProviderResult{$id=$_GET['section']??'';if(!is_string($id)){throw new ApiError(422,'BARS_SECTION_UNKNOWN','Выберите вкладку БАРС.');}BarsSections::authorize($a,$id);$result=$this->bars($a)->section($id);if($id!=='profile')return$result;return new ProviderResult($result->items,$result->source,$result->observedAt,$result->fixture,[...$result->details,'avatarVersion'=>UserAvatar::version($a->user['id'])]);}private function bars(Auth$a):BarsOfficialAdapter{$provider=ProviderFactory::make($a);if(!$provider instanceof BarsOfficialAdapter){throw new ApiError(503,'BLOCKED_EXTERNAL','Для кабинета нужен профиль БАРС.');}return$provider;}public function teacher(Auth$a,string$id):array{$m=$a->group();$teacher=DB::one('SELECT DISTINCT t.* FROM teachers t JOIN lesson_teachers lt ON lt.teacher_id=t.id JOIN class_meetings c ON c.id=lt.meeting_id WHERE t.id=? AND c.group_id=? AND c.term_id=?',[$id,$m['group_id'],$m['term_id']]);if(!$teacher){throw new ApiError(404,'NOT_FOUND','Преподаватель не найден');}[$from,$to]=self::range();return['teacher'=>$teacher,'schedule'=>ProviderFactory::make($a)->getTeacherSchedule($id,$from,$to)];}public function room(Auth$a,string$id):array{$m=$a->group();$room=DB::one('SELECT DISTINCT r.*,b.name AS building_name,b.address,b.lat,b.lon,b.location_verified AS building_verified FROM rooms r JOIN buildings b ON b.id=r.building_id JOIN class_meetings c ON c.room_id=r.id WHERE r.id=? AND c.group_id=? AND c.term_id=?',[$id,$m['group_id'],$m['term_id']]);if(!$room){throw new ApiError(404,'NOT_FOUND','Аудитория не найдена');}return$room;}public function syncStatus(Auth$a):array{return['provider'=>$this->providerState($a),'capabilities'=>ProviderFactory::make($a)->capabilities(),'runs'=>DB::all('SELECT id,provider,resource,trigger_type,started_at,ended_at,status,rows_changed,error_code,redacted_message FROM sync_runs WHERE user_id=? ORDER BY started_at DESC LIMIT 30',[$a->user['id']])];}private function providerState(Auth$a):string{return($a->publicUser()['barsConnected']??false)?'connected':'disconnected';}public function refresh(Auth$a):array{RateLimit::check('sync:'.$a->user['id'],1,300);$p=ProviderFactory::make($a);if($p instanceof BarsOfficialAdapter){$a->require('grades:read');$grades=$p->getGradesAndAssessments($a->membership['term_id']??'',true);$stale=!empty($grades->details['stale']);$message=$stale?'БАРС сейчас недоступен. Показаны последние полученные оценки.':'Оценки и КМ получены из БАРС.';DB::run("INSERT INTO sync_runs(id,user_id,provider,resource,trigger_type,ended_at,status,rows_changed,redacted_message) VALUES(?,?,'bars','grades','manual',UTC_TIMESTAMP(6),?,?,?)",[DB::id(),$a->user['id'],$stale?'stale':'success',$stale?0:count($grades->items),$message]);return['status'=>$stale?'stale':'connected','message'=>$message];}DB::run("INSERT INTO sync_runs(id,user_id,provider,resource,trigger_type,ended_at,status,error_code,redacted_message)
            VALUES(?,?,'bars','all','manual',UTC_TIMESTAMP(6),'blocked','BLOCKED_EXTERNAL','Подключение не настроено')",[DB::id(),$a->user['id']]);return['status'=>'BLOCKED_EXTERNAL','message'=>'БАРС не подключён; запросов в университет не было.'];}public function ics(Auth$a):never{[$from,$to]=self::range();$meetings=ProviderFactory::make($a)->getMySchedule($from,$to)->items;$homework=[];if(($_GET['homework']??'')==='1'){$a->require('homework:read');[$scope,$params]=Access::homeworkScope($a);$homework=DB::all("SELECT h.* FROM homework h WHERE $scope AND h.deleted_at IS NULL AND h.due_at>=? AND h.due_at<?",[...$params,$from,$to]);}header('Content-Type: text/calendar; charset=utf-8');header('Content-Disposition: attachment; filename="studpulse.ics"');header('Cache-Control: private, no-store');echo Calendar::export($meetings,$homework);exit;}}